/** True when `timeZone` is an IANA zone name that `Intl` recognises. */
export function isValidTimeZone(timeZone: string): boolean {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone });
    return true;
  } catch {
    return false;
  }
}

/** Throws a `RangeError` for a zone name `Intl` does not recognise. */
export function assertTimeZone(timeZone: string): void {
  if (!isValidTimeZone(timeZone)) {
    throw new RangeError(`Unknown time zone: "${timeZone}"`);
  }
}

const zoneFormatters = new Map<string, Intl.DateTimeFormat>();

function zoneFormatter(timeZone: string): Intl.DateTimeFormat {
  let formatter = zoneFormatters.get(timeZone);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hourCycle: "h23",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });
    zoneFormatters.set(timeZone, formatter);
  }
  return formatter;
}

interface ZoneFields {
  readonly year: number;
  readonly month: number;
  readonly day: number;
  readonly hour: number;
  readonly minute: number;
  readonly second: number;
}

/** The wall-clock fields `timeZone` shows at `instant`, to the second. */
function zoneFields(instant: Date, timeZone: string): ZoneFields {
  const parts: Record<string, number> = {};
  for (const part of zoneFormatter(timeZone).formatToParts(instant)) {
    if (part.type !== "literal") parts[part.type] = Number(part.value);
  }
  return {
    year: parts.year,
    month: parts.month,
    day: parts.day,
    hour: parts.hour,
    minute: parts.minute,
    second: parts.second,
  };
}

/** Milliseconds `timeZone` is ahead of UTC at `instant`. */
function zoneOffsetMs(instant: number, timeZone: string): number {
  const fields = zoneFields(new Date(instant), timeZone);
  const wallAsUtc = Date.UTC(
    fields.year,
    fields.month - 1,
    fields.day,
    fields.hour,
    fields.minute,
    fields.second,
  );
  return wallAsUtc - Math.floor(instant / 1000) * 1000;
}

function formatDay(year: number, month: number, day: number): string {
  return [
    String(year).padStart(4, "0"),
    String(month).padStart(2, "0"),
    String(day).padStart(2, "0"),
  ].join("-");
}

/** Shifts a `YYYY-MM-DD` calendar date by whole days. */
export function shiftLocalDate(date: string, days: number): string {
  const [year, month, day] = date.split("-").map(Number);
  const shifted = new Date(Date.UTC(year, month - 1, day + days));
  return formatDay(
    shifted.getUTCFullYear(),
    shifted.getUTCMonth() + 1,
    shifted.getUTCDate(),
  );
}

/** UTC epoch milliseconds of `hour`:00 on local calendar date `date`. */
function localHourMs(date: string, hour: number, timeZone: string): number {
  const [year, month, day] = date.split("-").map(Number);
  const wall = Date.UTC(year, month - 1, day, hour);
  const firstGuess = wall - zoneOffsetMs(wall, timeZone);
  return wall - zoneOffsetMs(firstGuess, timeZone);
}

/**
 * The `YYYY-MM-DD` calendar date that `value` falls on in `timeZone`. Used by
 * the activity feed's day grouping and by every "has this day ended" check.
 */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const fields = zoneFields(parseIso(value), timeZone);
  return formatDay(fields.year, fields.month, fields.day);
}

/** The local hour (0-23) `timeZone` shows at `reference`. */
export function localHour(reference: Date, timeZone: string): number {
  return zoneFields(reference, timeZone).hour;
}

/** The UTC instant at which local calendar date `date` begins in `timeZone`. */
export function startOfLocalDate(date: string, timeZone: string): IsoTimestamp {
  return toIsoTimestamp(new Date(localHourMs(date, 0, timeZone)));
}

/**
 * The UTC instant at which the zone's calendar day containing `reference`
 * began.
 */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  const fields = zoneFields(reference, timeZone);
  return startOfLocalDate(formatDay(fields.year, fields.month, fields.day), timeZone);
}

/**
 * True when a due date exists and its calendar day (on `timeZone`'s clock) has
 * already ended by `reference`. Due dates are whole days, so the due day
 * itself is never overdue.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  const today = localDate(toIsoTimestamp(reference), timeZone);
  return localDate(dueAt, timeZone) < today;
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
